  ('5b5d05fc-9921-56a0-9fff-bf795825ac6f', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'medium',
   $q$Some landowners call beavers "pests," while others call them "stubborn neighbors." How does "stubborn neighbors" differ in connotation?$q$, $q$[{"text":"It is harsher, because it suggests beavers are dangerous.","is_correct":false,"misconception_token":"reversed-connotation"},{"text":"It praises beavers fully and denies they cause any trouble.","is_correct":false,"misconception_token":"overstates-connotation"},{"text":"It means the same as \"pests,\" so the tone does not change.","is_correct":false,"misconception_token":"misses-connotation"},{"text":"It still admits a problem but treats beavers as belonging there.","is_correct":true}]$q$::jsonb, $q$It still admits a problem but treats beavers as belonging there.$q$, $q$"Stubborn" still points to a problem, but "neighbors" suggests beavers are part of the community rather than something to get rid of. The label is gentler, not identical to "pests," and the passage calls it "a gentler label."$q$, 'draft', '6bd74f3b-abac-5678-803e-68351084f0c7')
