  ('5858ec23-9a6d-528f-8aa4-640412469133', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'medium',
   $q$Why is "Students Stay Current" a pun for an article about a science club's electricity project?$q$, $q$[{"text":"\"Current\" means both a flow of water and up to date.","is_correct":false,"misconception_token":"ignores-context"},{"text":"\"Current\" sounds like \"currant,\" a fruit the club grew.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"\"Current\" means both a flow of electricity and up to date.","is_correct":true},{"text":"\"Current\" means both a flow of electricity and a river.","is_correct":false,"misconception_token":"misses-second-meaning"}]$q$::jsonb, $q$"Current" means both a flow of electricity and up to date.$q$, $q$The project is about electricity, and staying current also means keeping up to date, so both meanings fit the article. The water meaning exists, but it has nothing to do with an electricity project.$q$, 'draft', 'b50ed876-622f-562a-abf8-d73bb0d6af55')
