  ('6435a35e-632d-5a71-a239-e14be16dab80', null, (select id from public.skills where slug = 'read-g8-figurative-language'), null, 'easy',
   $q$Ms. Okonkwo glances at Rohan's empty hands and says, "I see you've brought your usual mountain of research." What does she really mean?$q$, $q$[{"text":"Rohan has been studying mountains for a project.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Rohan has come unprepared, as he often does.","is_correct":true},{"text":"Rohan has left his research somewhere in the room.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Rohan has brought more notes than anyone else.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$Rohan has come unprepared, as he often does.$q$, $q$This is verbal irony: she says "mountain" while looking at his empty hands, meaning he brought nothing. Taking "mountain of research" at face value contradicts the detail that he arrived with "no notes."$q$, 'draft', 'f94e5168-e149-5020-a7a6-b2ff9676ff2b')
